//
// Listing the app commands makes Tauri generate an `allow-<command>`
// permission for each (under permissions/autogenerated/) and deny any
// command a capability does not grant. The development commands
// (src/dev_commands.rs) exist only in builds with debug assertions, and so
// do their permissions and the capabilities that grant them
// (capabilities/dev/): every other build neither registers the commands
// nor generates or loads those.

include!("src/dev_command_names.rs");

const APP_COMMANDS: &[&str] = &[
    // src/hid_commands.rs
    "list_devices",
    "open_device",
    "close_device",
    "send_receive",
    "send",
    "is_device_open",
    // src/definition.rs
    "decompress_definition",
];

const AUTOGENERATED_PERMISSIONS: &str = "permissions/autogenerated";

/// Removes the generated permission files of commands this build does not
/// have. Debug and release builds share the directory, and Tauri loads
/// every file in it, so a development permission left by a debug build
/// would otherwise reach a release build.
fn remove_stale_permissions(commands: &[&str]) {
    let Ok(entries) = std::fs::read_dir(AUTOGENERATED_PERMISSIONS) else {
        return;
    };
    for entry in entries.flatten() {
        let path = entry.path();
        let stale = path.extension().is_some_and(|ext| ext == "toml")
            && path.file_stem().and_then(|stem| stem.to_str()).is_some_and(|name| !commands.contains(&name));
        if stale && let Err(err) = std::fs::remove_file(&path) {
            eprintln!("failed to remove {}: {err}", path.display());
            std::process::exit(1);
        }
    }
}

fn main() {
    println!("cargo:rerun-if-changed=capabilities");
    println!("cargo:rerun-if-changed=src/dev_command_names.rs");
    // Set by Cargo for the crate being built, so they follow the profile and
    // the target rather than the build script's own.
    let debug = std::env::var_os("CARGO_CFG_DEBUG_ASSERTIONS").is_some();
    let linux = std::env::var("CARGO_CFG_TARGET_OS").is_ok_and(|os| os == "linux");

    let mut commands = APP_COMMANDS.to_vec();
    if debug {
        commands.extend_from_slice(DEV_COMMANDS);
        if linux {
            commands.extend_from_slice(LINUX_DEV_COMMANDS);
        }
    }
    // tauri-build keeps the list for the rest of the build script.
    let commands: &'static [&'static str] = commands.leak();
    remove_stale_permissions(commands);

    let capabilities = if debug { "./capabilities/**/*.json" } else { "./capabilities/*.json" };
    let attributes = tauri_build::Attributes::new()
        .app_manifest(tauri_build::AppManifest::new().commands(commands))
        .capabilities_path_pattern(capabilities);
    if let Err(err) = tauri_build::try_build(attributes) {
        eprintln!("tauri-build failed: {err:#}");
        std::process::exit(1);
    }
}
